bash -c 'LOG="$HOME/.ax/push.log"; mkdir -p "$(dirname "$LOG")"; TS() { date +%Y-%m-%dT%H:%M:%S; }; INPUT=$(cat); CWD=$(echo "$INPUT" | grep -o "\"cwd\": *\"[^\"]*\"" | cut -d\" -f4); if [ -z "$CWD" ]; then echo "[$(TS)] skip: no cwd in hook input" >> "$LOG"; exit 0; fi; PUSH_REPO=""; if [ -e "$CWD/.git" ]; then PUSH_REPO="$CWD"; else REPO=$(echo "$CWD" | sed -n "s|/\.claude/worktrees/.*||p"); if [ -n "$REPO" ] && [ -d "$REPO/.git" ]; then PUSH_REPO="$REPO"; fi; fi; if [ -z "$PUSH_REPO" ]; then echo "[$(TS)] skip: no git repo at $CWD" >> "$LOG"; exit 0; fi; OUTPUT=$(/usr/local/bin/ax push --repo "$PUSH_REPO" 2>&1); RC=$?; if [ -n "$OUTPUT" ]; then echo "$OUTPUT" | while IFS= read -r line; do [ -n "$line" ] && echo "[$(TS)] $line" >> "$LOG"; done; fi; if [ $RC -eq 0 ]; then echo "[$(TS)] ok: push completed for $PUSH_REPO" >> "$LOG"; else echo "[$(TS)] error: push failed for $PUSH_REPO (exit $RC)" >> "$LOG"; fi'